"""
Conditional volatility-managed index: de-risk only in a stressed downtrend.

Monthly: if the broad index ETF is above its 200-day simple moving average,
hold it at 100%. If it is below, scale exposure to min(1, 15% / realised
volatility of the past 21 days) and put the rest in short-term Treasuries.
This works out to: a calm market below trend stays fully invested, and a
volatile market above trend stays fully invested. Exposure is cut only when
the index is both below trend and volatile, the regime where high volatility
has tended to persist and returns have been poor. Parameters are the standard
textbook values (200-day SMA, 1-month volatility, 15% target, about US
stocks' long-run volatility) and are not tuned.
"""

import math

import pandas as pd

from shared.strategy import PriceView, Strategy
from shared.universe import etf


class StressedTrendVolGate(Strategy):
    name = "stressed_trend_vol_gate"
    rebalance = "monthly"

    def __init__(self, sma_window: int = 200, vol_lookback: int = 21,
                 target: float = 0.15):
        self.sma_window = sma_window
        self.vol_lookback = vol_lookback
        self.target = target

    def params(self) -> dict:
        return {"sma_days": self.sma_window, "vol_lookback_days": self.vol_lookback,
                "target_vol_annual": self.target, "off_asset": "short_bond",
                "rule": "full index unless below SMA AND vol > target"}

    def target_weights(self, data: PriceView) -> pd.Series:
        index = etf("broad_index")
        safe = etf("short_bond")
        if index not in data.close.columns:
            return pd.Series(dtype=float)
        px = data.close[index].dropna()
        if len(px) < max(self.sma_window, self.vol_lookback + 1):
            return pd.Series({index: 1.0})

        last = px.iloc[-1]
        sma = px.iloc[-self.sma_window:].mean()
        if last >= sma:
            return pd.Series({index: 1.0})

        rets = px.iloc[-1 - self.vol_lookback:].pct_change().iloc[1:]
        vol = rets.std() * math.sqrt(252)
        if not (vol > 0) or vol <= self.target:
            return pd.Series({index: 1.0})

        w = min(1.0, self.target / vol)
        out = {index: w}
        safe_ok = safe in data.close.columns and pd.notna(data.close[safe].iloc[-1])
        if w < 1.0 and safe_ok:
            out[safe] = 1.0 - w
        return pd.Series(out)

"""
Anchoring / 52-week-high momentum (George & Hwang 2004), long-only.

Monthly: across the 19 stocks and 9 sector ETFs, score each name by its close
divided by its highest close of the prior 252 trading days, averaged over the
last 21 days to damp rank noise. Hold the 6 highest-scoring names at equal
weight (1/6 each, under the 25% cap). If fewer than 6 names have enough
history, the unused weight goes to the broad index ETF. Fixed parameters,
not tuned.
"""

import pandas as pd

from shared.strategy import PriceView, Strategy
from shared.universe import STOCKS, SECTOR_ETFS, etf


class NearHigh(Strategy):
    name = "near_52w_high_top6"
    rebalance = "monthly"

    def __init__(self, n_hold: int = 6, high_window: int = 252, smooth: int = 21):
        self.n_hold, self.high_window, self.smooth = n_hold, high_window, smooth

    def params(self) -> dict:
        return {"n_hold": self.n_hold, "high_window_days": self.high_window,
                "smooth_days": self.smooth, "universe": "stocks+sector_etfs",
                "weighting": "equal", "fallback": "broad_index"}

    def target_weights(self, data: PriceView) -> pd.Series:
        index = etf("broad_index")
        cands = [t for t in list(STOCKS) + list(SECTOR_ETFS) if t in data.close.columns]
        need = self.high_window + self.smooth
        close = data.close[cands].iloc[-need:]

        scores = {}
        if len(close) >= need:
            roll_max = close.rolling(self.high_window, min_periods=self.high_window).max()
            ratio = (close / roll_max).iloc[-self.smooth:]
            for t in cands:
                col = ratio[t]
                if col.notna().all() and close[t].notna().all():
                    scores[t] = float(col.mean())

        w = 1.0 / self.n_hold
        out = {}
        if scores:
            s = pd.Series(scores)
            s = s.sort_index().sort_values(ascending=False, kind="mergesort")
            for t in s.index[: self.n_hold]:
                out[t] = w

        leftover = 1.0 - w * len(out)
        if leftover > 1e-9:
            out[index] = out.get(index, 0.0) + leftover
        return pd.Series(out, dtype=float)

"""
Volatility-scaled stock momentum with a rank buffer (Jegadeesh & Titman 1993;
Barroso & Santa-Clara 2015, "Momentum has its moments"; long-only, no leverage).

Monthly: rank the stocks by 12-1 month return. Hold 5 names equal-weighted.
A held name is kept while it still ranks in the top 8; free slots are filled
from the top of the ranking. The holdings path is replayed over all past
month-ends from the data, so no state is kept between calls.
Exposure = min(1, 25% / realised 126-day volatility of the held basket);
the rest goes to short-term Treasuries. Parameters are the standard published
ones and were not tuned.
"""

import math

import numpy as np
import pandas as pd

from shared.strategy import PriceView, Strategy
from shared.universe import STOCKS, etf


class VolScaledMomentumBuffer(Strategy):
    name = "vol_scaled_momentum_buffer"
    rebalance = "monthly"

    def __init__(self, top_n: int = 5, keep_rank: int = 8, lookback: int = 252,
                 skip: int = 21, vol_window: int = 126, target_vol: float = 0.25):
        self.top_n = top_n
        self.keep_rank = keep_rank
        self.lookback = lookback
        self.skip = skip
        self.vol_window = vol_window
        self.target_vol = target_vol

    def params(self) -> dict:
        return {"top_n": self.top_n, "keep_while_rank_within": self.keep_rank,
                "momentum": "12-1 month", "lookback_days": self.lookback,
                "skip_days": self.skip, "vol_window_days": self.vol_window,
                "target_vol_annual": self.target_vol, "max_exposure": 1.0,
                "off_asset": "short_bond"}

    def target_weights(self, data: PriceView) -> pd.Series:
        off = etf("short_bond")
        cols = [s for s in STOCKS if s in data.close.columns]
        if not cols:
            return pd.Series({off: 1.0})
        close = data.close[cols]
        n = len(close)
        if n <= self.lookback:
            return pd.Series({off: 1.0})

        dates = pd.DatetimeIndex(close.index)
        months = dates.month
        ends = [i for i in range(n)
                if i >= self.lookback and (i == n - 1 or months[i] != months[i + 1])]
        if not ends:
            return pd.Series({off: 1.0})

        arr = close.to_numpy(dtype=float)
        names = list(cols)
        held: list = []
        for i in ends:
            past = arr[i - self.lookback]
            recent = arr[i - self.skip]
            now = arr[i]
            with np.errstate(divide="ignore", invalid="ignore"):
                mom = recent / past - 1.0
            valid = np.isfinite(mom) & np.isfinite(now) & (past > 0)
            idx = [j for j in range(len(names)) if valid[j]]
            if not idx:
                held = []
                continue
            order = sorted(idx, key=lambda j: -mom[j])
            ranked = [names[j] for j in order]
            rank = {t: r for r, t in enumerate(ranked)}
            keep = [t for t in held if t in rank and rank[t] < self.keep_rank]
            keep.sort(key=lambda t: rank[t])
            new = keep[: self.top_n]
            for t in ranked:
                if len(new) >= self.top_n:
                    break
                if t not in new:
                    new.append(t)
            held = new

        if not held:
            return pd.Series({off: 1.0})

        window = close[held].iloc[-self.vol_window - 1:]
        rets = window.pct_change().iloc[1:]
        port = rets.mean(axis=1, skipna=True).dropna()
        scale = 1.0
        if len(port) > 20:
            vol = float(port.std()) * math.sqrt(252)
            if vol > 0 and math.isfinite(vol):
                scale = min(1.0, self.target_vol / vol)

        each = scale / len(held)
        out = {t: each for t in held}
        if scale < 1.0:
            out[off] = 1.0 - scale
        return pd.Series(out)
